"""Original standalone Physics questions. Rebuild without altering lesson content."""
import json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
DATA={}
def question(prompt,rows):return {'prompt':prompt,'marking':[{'point':r,'marks':1} for r in rows],'marks':len(rows),'lines':max(5,len(rows)*2)}
def num(prompt,equation,substitution,answer,interpret=None):return question(prompt,[equation,substitution,answer]+([interpret] if interpret else []))
def check(prompt,options,answer,why):return {'prompt':prompt,'options':options,'answer':answer,'why':why,'marks':1}
def add(id,definition,calc,application,explanation,checks,visual):
 DATA[id]={'questions':[question(*definition),calc,application,question(*explanation)],'mastery':checks,'visual':visual}
add('y11-foundations',('Distinguish precision from accuracy in a length measurement.',['Precision concerns agreement between repeated readings.','Accuracy concerns closeness to an accepted / true value.']),num('A block has mass (0.240 ± 0.003) kg and volume (8.0 ± 0.2) × 10⁻⁵ m³. Calculate its density, ignoring uncertainty for this part.','ρ = m / V.','ρ = 0.240 / (8.0 × 10⁻⁵).','ρ = 3.0 × 10³ kg m⁻³, to two significant figures.'),num('Use the conservative sum-of-percentage-uncertainties method to estimate the density uncertainty for the same block. Express the result with an absolute uncertainty.','For a quotient, add the percentage uncertainties.','Mass uncertainty = 1.25%; volume uncertainty = 2.5%; total = 3.75%.','Absolute uncertainty = 3000 × 0.0375 = 112.5 kg m⁻³.','A suitable report is (3.00 ± 0.11) × 10³ kg m⁻³; uncertainty is an estimate, not a correction.'),('Every reading from a balance is 0.010 kg too high. Explain why taking ten readings does not remove this problem and propose a correction.',['A constant offset is a systematic error.','Averaging reduces random scatter but retains the offset.','Zero / calibrate the balance against a reference, or subtract the established offset.']),[check('How many significant figures are in 0.00480?',['2','3','4','5'],1,'Leading zeros do not count; the trailing zero after the decimal does.'),check('Which is the SI unit of a velocity gradient with respect to time?',['m','m s⁻¹','m s⁻²','s m⁻¹'],2,'Velocity change divided by time is acceleration.')],'measurement')
add('y11-vectors',('Distinguish displacement from distance for a journey.',['Displacement is the vector change in position.','Distance is the scalar length of the travelled path.']),num('A walker travels 120 m east and then 50 m north. Calculate the magnitude of displacement.','d = √(120² + 50²).','d = √16900.','d = 130 m.'),num('The journey takes 85 s. Calculate the average velocity, stating magnitude and direction.','Average velocity magnitude = displacement / time.','v = 130 / 85 = 1.53 m s⁻¹.','θ = tan⁻¹(50 / 120) = 22.6° north of east.','Report 1.5 m s⁻¹ at 23° north of east; distance / time would give average speed instead.'),('A runner completes a lap and returns to the start. Explain how average speed can be non-zero while average velocity is zero.',['Distance travelled is positive.','Net displacement is zero.','Average speed uses distance / time; average velocity uses displacement / time.']),[check('Which quantity is a vector?',['Energy','Mass','Velocity','Temperature'],2,'Velocity includes a direction.'),check('A force has perpendicular components 6 N and 8 N. Its magnitude is:',['2 N','7 N','10 N','14 N'],2,'Pythagoras gives √(36 + 64) = 10 N.')],'vectors')
add('y11-motion-graphs',('State what the gradient and signed area of a velocity–time graph represent.',['Gradient represents acceleration.','Signed area represents displacement.']),num('A trolley accelerates uniformly from 2.0 to 10.0 m s⁻¹ in 4.0 s. Calculate its acceleration.','a = (v − u) / t.','a = (10.0 − 2.0) / 4.0.','a = 2.0 m s⁻².'),num('The trolley then maintains 10.0 m s⁻¹ for 3.0 s. Calculate its total displacement across both stages.','Accelerating-stage displacement = average velocity × time.','s₁ = ((2 + 10) / 2) × 4 = 24 m.','Constant-speed displacement s₂ = 10 × 3 = 30 m; total = 54 m.','Both velocities are positive, so both areas contribute positive displacement.'),('A student says a horizontal position–time graph means constant non-zero speed. Correct this claim.',['A horizontal graph has zero gradient.','Position is not changing, so velocity is zero.','Constant non-zero velocity needs a straight line with a non-zero gradient.']),[check('An object has negative velocity and positive acceleration. Initially it is:',['Speeding up in the negative direction','Slowing down','Stationary throughout','Moving with constant speed'],1,'Opposite signs of velocity and acceleration initially reduce speed.'),check('A velocity–time graph crosses below zero. The area below zero is:',['Positive displacement','Negative displacement','Always zero','Acceleration'],1,'The signed area below the time axis is negative displacement.')],'motion')
add('y11-kinematics',('State two assumptions needed to use the standard constant-acceleration equations for a vertical throw.',['Acceleration is treated as constant (near Earth, g ≈ 9.8 m s⁻² downward).','Air resistance is neglected.']),num('A ball is thrown vertically upward at 18.0 m s⁻¹. Take upward as positive and g = 9.8 m s⁻². Calculate the time to its highest point.','v = u + at, with v = 0 at the top.','t = (0 − 18.0) / (−9.8).','t = 1.84 s.'),num('The ball returns to the release height. Calculate its maximum rise and total flight time.','v² = u² + 2as gives h = u² / (2g).','h = 18.0² / (2 × 9.8) = 16.5 m.','Total time = 2u / g = 3.67 s.','Equal ascent and descent times apply because the release and landing heights match and drag is neglected.'),('At the highest point, a student claims the ball has zero acceleration. Explain the error.',['Instantaneous velocity is zero at the top.','Gravity still acts, producing downward acceleration g.','The downward acceleration changes the upward motion into downward motion.']),[check('A car moving at 20 m s⁻¹ brakes with acceleration −5 m s⁻². Stopping time is:',['2 s','4 s','5 s','100 s'],1,'0 = 20 − 5t gives t = 4 s.'),check('In a drag-free vertical throw, which quantity remains constant?',['Velocity','Height','Acceleration','Kinetic energy'],2,'Gravitational acceleration is approximated as constant.')],'vertical')
add('y11-newton',('State Newton’s first law and identify the force condition it requires.',['An object remains at rest or continues with constant velocity unless acted on by a net force.','The relevant condition is zero resultant force, not absence of all forces.']),num('A 72 kg passenger is in a lift accelerating upward at 1.5 m s⁻². Take g = 9.8 m s⁻². Calculate the normal force from the floor.','N − mg = ma.','N = 72(9.8 + 1.5).','N = 814 N (approximately).'),num('The lift instead accelerates downward at 2.0 m s⁻². Find the normal force and compare it with the passenger’s weight.','Taking upward positive, N − mg = m(−2.0).','N = 72(9.8 − 2.0) = 562 N.','Weight = 72 × 9.8 = 706 N.','Normal force is smaller than weight, so apparent weight decreases; gravitational weight is unchanged.'),('Explain why the passenger’s weight and the normal force are not a Newton’s third-law pair.',['Both forces act on the passenger.','A third-law pair acts on two different interacting objects.','The partner of Earth pulling the passenger is the passenger pulling Earth; the normal partner acts on the floor.']),[check('Net force is zero. Which motion is possible?',['Only rest','Only acceleration','Constant velocity','Changing direction at constant speed'],2,'Zero net force means zero acceleration.'),check('A 3 kg object has a net force of 12 N. Its acceleration is:',['0.25 m s⁻²','4 m s⁻²','9 m s⁻²','36 m s⁻²'],1,'a = F / m = 4 m s⁻².')],'forces')
add('y11-friction-slopes',('Distinguish static and kinetic friction.',['Static friction opposes impending relative sliding and adjusts up to a maximum.','Kinetic friction acts when surfaces are sliding; its magnitude is modelled by μₖN.']),num('A 5.0 kg block slides on a horizontal surface with μₖ = 0.20. Find the friction magnitude. Take g = 9.8 m s⁻².','fₖ = μₖN; N = mg for this horizontal case.','fₖ = 0.20 × 5.0 × 9.8.','fₖ = 9.8 N.'),num('A 6.0 kg block slides down a 30° slope with μₖ = 0.15. Calculate its acceleration.','N = mg cos θ; fₖ = μₖmg cos θ acts upslope.','Net downslope force = mg sin θ − μₖmg cos θ.','a = 9.8(sin 30° − 0.15 cos 30°) = 3.63 m s⁻² downslope.','Mass cancels in this ideal model; do not use N = mg on the slope.'),('A stationary block has a maximum static friction of 18 N. A 10 N horizontal pull is applied. Explain its friction and motion.',['Static friction adjusts to 10 N, opposing the pull.','The maximum 18 N is a limit, not the friction in every situation.','Net horizontal force is zero, so the block remains at rest.']),[check('A block rests on an incline with no other perpendicular force. Normal force is:',['mg','mg sin θ','mg cos θ','mg tan θ'],2,'The perpendicular weight component is mg cos θ.'),check('Sliding friction acts:',['Always downward','Along the normal','Opposite relative sliding','In the direction of acceleration in every case'],2,'It opposes relative sliding of the contact surfaces.')],'slope')
add('y11-momentum-impulse',('Define momentum and impulse and state their connection.',['Momentum is p = mv, a vector.','Impulse is the net-force time integral / FΔt for a constant force and equals change in momentum.']),num('A 0.060 kg ball moving at 25 m s⁻¹ is brought to rest. Find the impulse on the ball, taking its initial direction as positive.','J = Δp = m(v − u).','J = 0.060(0 − 25).','J = −1.5 N s, opposite the initial motion.'),num('The stopping time is increased from 0.010 s to 0.060 s. Calculate the magnitudes of the average forces and their ratio.','|Favg| = |Δp| / Δt for the same momentum change.','Short stop: 1.5 / 0.010 = 150 N.','Long stop: 1.5 / 0.060 = 25 N; short / long = 6.0.','Increasing stop time reduces average force for the same impulse; peak force need not equal average force.'),('Explain how an airbag can reduce injury without reducing the passenger’s required momentum change to zero.',['The passenger still changes momentum from moving to rest.','The airbag increases stopping time / distance.','For the same momentum change, a longer stopping time reduces average force.']),[check('The area under a net force–time graph is:',['Power','Impulse','Velocity','Mass'],1,'Force × time has impulse units N s.'),check('Doubling mass at the same velocity makes momentum:',['Half','Unchanged','Double','Four times'],2,'Momentum is proportional to mass.')],'impulse')
add('y11-collisions',('State the condition for momentum conservation and distinguish it from kinetic-energy conservation.',['Total momentum is conserved if external impulse on the system is negligible.','Kinetic energy is conserved only in an elastic collision, not all collisions.']),num('A 1.5 kg trolley at 4.0 m s⁻¹ collides with a stationary 2.5 kg trolley and they stick. Find their common velocity.','m₁u₁ + m₂u₂ = (m₁ + m₂)v.','1.5 × 4.0 + 2.5 × 0 = 4.0v.','v = 1.5 m s⁻¹ in the first trolley’s initial direction.'),num('For that collision, calculate the kinetic energy transformed into other forms.','Initial KE = ½m₁u₁² + ½m₂u₂².','Initial KE = ½ × 1.5 × 4.0² = 12.0 J.','Final KE = ½ × 4.0 × 1.5² = 4.5 J; decrease = 7.5 J.','The decrease becomes internal energy, sound or deformation; total energy remains conserved.'),('Explain why equal and opposite collision forces do not imply equal accelerations for unequal masses.',['The interaction forces have equal magnitudes by Newton’s third law.','Acceleration is F / m.','The smaller mass experiences a larger acceleration magnitude for the same force magnitude.']),[check('Two objects stick after a collision. The collision is:',['Perfectly elastic','Perfectly inelastic','Momentum-free','Necessarily frictionless'],1,'Sticking identifies a perfectly inelastic collision.'),check('A closed system initially has zero momentum. After an explosion its total momentum is:',['Positive','Negative','Zero','Equal to total kinetic energy'],2,'Internal forces cannot change total momentum without external impulse.')],'collision')
add('y11-work-energy-power',('Distinguish work done by a force from power.',['Work is force component along displacement multiplied by displacement / W = Fs cos θ.','Power is the rate of energy transfer / P = W / t.']),num('A 40 N force pulls a crate 6.0 m horizontally at 30° above horizontal. Find the work done by this force.','W = Fs cos θ.','W = 40 × 6.0 × cos 30°.','W = 208 J (approximately).'),num('A hoist raises 18 kg through 3.5 m in 7.0 s. Its input power is 140 W. Find useful output power and efficiency. Take g = 9.8 m s⁻².','Useful energy = mgh = 18 × 9.8 × 3.5 = 617.4 J.','Useful output power = 617.4 / 7.0 = 88.2 W.','Efficiency = 88.2 / 140 × 100 = 63.0%.','The remaining input power is transferred to other forms; energy is not destroyed.'),('A satellite’s instantaneous displacement is perpendicular to the gravitational force in a circular orbit. Explain gravitational work in that ideal case.',['Work uses the force component along displacement.','The angle between force and instantaneous displacement is 90°.','Fs cos 90° = 0, so gravity changes direction of velocity without changing speed.']),[check('Doubling speed at the same mass multiplies kinetic energy by:',['½','2','4','8'],2,'KE = ½mv².'),check('A machine supplies 300 J in 6 s. Power is:',['50 W','306 W','1800 W','0.02 W'],0,'Power is energy / time.')],'energy')
add('y11-heat-temperature',('Distinguish temperature from internal energy.',['Temperature indicates average particle kinetic energy in the usual thermal model.','Internal energy is the total microscopic kinetic and potential energy of the system.']),num('Convert −18 °C and 95 °C to kelvin. Use T(K) = T(°C) + 273.15.','Add 273.15 to each Celsius temperature.','−18 + 273.15 = 255.15; 95 + 273.15 = 368.15.','The temperatures are approximately 255 K and 368 K.'),num('A metal block receives 850 J by heating and does 120 J of work on its surroundings. Calculate its internal-energy change using ΔU = Q − W, where W is work done by the system.','Use ΔU = Q − W with the stated sign convention.','Q = +850 J and W = +120 J.','ΔU = 850 − 120 = +730 J.','Internal energy increases; the work transfers some received energy to the surroundings.'),('Two water samples have the same temperature but one has twice the mass. Explain why equal temperature does not mean equal internal energy.',['The average microscopic kinetic energy per particle is similar.','The larger sample contains more particles.','For the same state and composition, its total internal energy is greater despite equal temperature.']),[check('A temperature rise of 12 °C equals a rise of:',['12 K','261 K','285 K','−12 K'],0,'Kelvin and Celsius intervals have equal size.'),check('Heat is best described as:',['A substance in hot objects','Energy transferred because of a temperature difference','The number of particles','The same quantity as temperature'],1,'Heat denotes thermal energy transfer.')],'thermal')
add('y11-specific-latent',('Explain the difference between specific heat capacity and specific latent heat.',['Specific heat capacity is energy per kilogram per kelvin of temperature change.','Specific latent heat is energy per kilogram for a specified phase change without temperature change.']),num('Find the energy needed to heat 0.35 kg of water from 18 °C to 65 °C. Use c = 4200 J kg⁻¹ K⁻¹.','Q = mcΔT.','Q = 0.35 × 4200 × (65 − 18).','Q = 6.9 × 10⁴ J to two significant figures (unrounded value 69090 J).'),num('A 0.12 kg ice sample at 0 °C melts, then warms to 25 °C. Use Lf = 3.34 × 10⁵ J kg⁻¹ and cwater = 4200 J kg⁻¹ K⁻¹. Find total energy.','Melting energy Q₁ = mLf.','Q₁ = 0.12 × 3.34 × 10⁵ = 40080 J.','Warming energy Q₂ = 0.12 × 4200 × 25 = 12600 J; total = 52680 J.','Both stages require energy; a melting-only calculation omits the later temperature rise.'),('Explain why temperature stays constant during melting even though energy is supplied.',['Supplied energy increases microscopic potential energy by changing particle arrangement / overcoming bonds.','Average particle kinetic energy does not rise during the phase change.','Temperature remains constant while both phases coexist at the melting condition.']),[check('Which expression is used for melting at constant temperature?',['mcΔT','mL','½mv²','mg'],1,'Latent heat uses Q = mL.'),check('For the same mass and temperature rise, doubling c makes required heat:',['Half','Unchanged','Double','Four times'],2,'Q = mcΔT is proportional to c.')],'heating')
add('y11-transfer-calorimetry',('State the energy-transfer mechanisms in conduction and convection.',['Conduction transfers energy through particle interactions / free electrons without bulk flow.','Convection transfers energy through bulk movement of a fluid.']),num('Mix 0.20 kg of water at 80 °C with 0.30 kg at 20 °C. Ignore container heat capacity and heat loss. Find equilibrium temperature.','Heat lost by hot water equals heat gained by cold water.','0.20c(80 − T) = 0.30c(T − 20).','T = 44 °C.'),num('A 0.10 kg metal at 95 °C is placed in 0.25 kg water at 20 °C. Equilibrium is 23 °C. Find the metal’s specific heat capacity, using cwater = 4200 J kg⁻¹ K⁻¹ and neglecting losses.','mmetal cmetal(95 − 23) = mwater cwater(23 − 20).','Water energy gain = 0.25 × 4200 × 3 = 3150 J.','cmetal = 3150 / (0.10 × 72) = 438 J kg⁻¹ K⁻¹.','This assumes negligible heat absorbed by the container; include its heat capacity for a better model.'),('Explain why a vacuum flask uses both a vacuum gap and reflective surfaces.',['The vacuum reduces conduction and convection across the gap.','Thermal radiation can cross a vacuum.','Reflective surfaces reduce radiative transfer by reducing absorption / emission.']),[check('At thermal equilibrium, objects in contact have the same:',['Mass','Internal energy','Temperature','Specific heat capacity'],2,'Equal temperature means no net heat transfer.'),check('Which transfer mechanism can operate across a vacuum?',['Conduction through air','Convection','Radiation','Bulk fluid flow'],2,'Electromagnetic radiation does not need matter.')],'calorimetry')
add('y11-wave-foundations',('Distinguish transverse and longitudinal waves.',['Transverse oscillations are perpendicular to propagation.','Longitudinal oscillations are parallel to propagation.']),num('A wave has frequency 8.0 Hz and wavelength 0.45 m. Calculate its speed.','v = fλ.','v = 8.0 × 0.45.','v = 3.6 m s⁻¹.'),num('A water wave travels at 1.8 m s⁻¹ with period 0.60 s. Calculate its frequency and wavelength.','f = 1 / T.','f = 1 / 0.60 = 1.67 Hz.','λ = v / f = 1.8 / 1.67 = 1.08 m.','Period describes time between oscillations; wavelength describes distance between equal-phase positions.'),('Explain why a displacement–distance snapshot cannot by itself show the propagation direction.',['The snapshot shows spatial displacement at one instant.','Right-travelling and left-travelling waves can have the same instantaneous profile.','A later snapshot / particle motion information is needed to establish propagation direction.']),[check('Increasing amplitude primarily changes a wave’s:',['Frequency by definition','Energy carried','Wavelength by definition','Medium'],1,'Larger amplitude generally carries greater wave energy.'),check('A 25 Hz oscillation has period:',['25 s','0.04 s','4 s','625 s'],1,'T = 1 / f.')],'wave')
add('y11-wave-behaviour',('State what happens to frequency and wavelength when a wave enters a medium where it travels more slowly.',['Frequency remains fixed by the source.','Wavelength decreases because λ = v / f.']),num('An ultrasound pulse returns from a boundary after 0.00016 s. Sound speed is 1500 m s⁻¹. Find the boundary depth.','Distance to boundary = vt / 2.','d = 1500 × 0.00016 / 2.','d = 0.12 m.'),num('A wave crosses into another medium: speed changes from 3.0 to 2.0 m s⁻¹ while frequency stays 5.0 Hz. Calculate both wavelengths and explain the change.','λ₁ = v₁ / f.','λ₁ = 3.0 / 5.0 = 0.60 m.','λ₂ = 2.0 / 5.0 = 0.40 m.','The source frequency is unchanged, so reduced speed gives reduced spacing between crests.'),('Explain why a wave spreads more strongly through a narrow gap than a very wide gap, relative to wavelength.',['Diffraction is spreading at a gap / edge.','Spreading is pronounced when gap width is comparable to wavelength.','When gap width is much larger than wavelength, the central wavefront spreads less strongly.']),[check('An echo calculation divides total travel distance by two because sound:',['Has half its usual speed','Travels outward and back','Has two frequencies','Stops at the wall'],1,'The measured time includes the return journey.'),check('Refraction occurs because wave:',['Frequency always doubles','Speed changes between regions','Energy must become zero','Amplitude must increase'],1,'A speed change can change propagation direction at an oblique boundary.')],'refraction')
add('y11-wave-interference',('State the requirements for sustained interference and distinguish constructive from destructive interference.',['Sources must be coherent: same frequency and a stable phase relationship.','In-phase contributions reinforce; opposite-phase contributions cancel partly or fully.']),num('Two in-phase sources have wavelength 0.080 m. A point has path difference 0.24 m. Determine the interference type.','Constructive interference for in-phase sources occurs at Δr = nλ.','Δr / λ = 0.24 / 0.080 = 3.','The path difference is three wavelengths, so interference is constructive.'),num('Two tuning forks have frequencies 256 Hz and 262 Hz. Calculate beat frequency and the time between successive loud maxima.','Beat frequency = |f₂ − f₁|.','fbeat = |262 − 256| = 6 Hz.','Time between loud maxima = 1 / 6 = 0.167 s.','Beat frequency describes the amplitude envelope, not the carrier oscillation frequency.'),('Explain why cancellation at one location does not mean wave energy has been destroyed everywhere.',['Superposition can produce zero resultant displacement at a point.','The interference pattern also contains enhanced-amplitude regions.','Energy is redistributed / transferred rather than destroyed; local cancellation is not global absence of waves.']),[check('For equal coherent in-phase sources, a half-wavelength path difference gives:',['Constructive interference','Destructive interference','No phase change','Double frequency'],1,'A half-wavelength path difference corresponds to opposite phase.'),check('Frequencies of 440 and 443 Hz produce beats at:',['3 Hz','441.5 Hz','883 Hz','1320 Hz'],0,'Beat frequency is the absolute difference.')],'interference')
add('y11-standing-waves',('Distinguish a node from an antinode in a standing wave.',['A node has zero oscillation amplitude.','An antinode has maximum oscillation amplitude.']),num('A string fixed at both ends is 0.90 m long. Wave speed is 72 m s⁻¹. Find the fundamental frequency.','For the fundamental, λ₁ = 2L and f₁ = v / 2L.','f₁ = 72 / (2 × 0.90).','f₁ = 40 Hz.'),num('A pipe closed at one end has length 0.85 m. Use sound speed 340 m s⁻¹. Find the fundamental and the next resonant frequency in the ideal model.','For a closed–open pipe, f₁ = v / 4L.','f₁ = 340 / (4 × 0.85) = 100 Hz.','The next allowed harmonic is the third: f₃ = 300 Hz.','Only odd harmonics occur in this ideal closed–open model; end corrections are neglected.'),('Explain how two oppositely travelling waves can form a stationary node pattern.',['Waves of the same frequency and suitable amplitude travel in opposite directions.','Their interference produces fixed locations of cancellation and reinforcement.','Particles oscillate but the node pattern does not translate along the medium.']),[check('Adjacent nodes are separated by:',['λ/4','λ/2','λ','2λ'],1,'A node-to-node interval spans half a wavelength.'),check('A string fixed at both ends supports:',['Only odd harmonics','Only even harmonics','All positive integer harmonics','No harmonics'],2,'Its permitted wavelengths are 2L/n.')],'standing')
add('y11-nuclear-structure',('Distinguish isotopes from ions of an element.',['Isotopes have the same proton number but different neutron numbers.','Ions have gained or lost electrons, altering charge without changing nuclear proton number.']),num('An atom has atomic number 17 and mass number 37. Calculate its proton and neutron numbers and the electrons in its 1− ion.','Protons = Z; neutrons = A − Z.','Protons = 17; neutrons = 37 − 17 = 20.','The 1− ion has 18 electrons.'),num('A nucleus with A = 210 and Z = 84 emits one alpha particle. Find the daughter’s A and Z and name the conserved quantities used.','An alpha particle has A = 4 and Z = 2.','Daughter mass number = 210 − 4 = 206.','Daughter atomic number = 84 − 2 = 82.','The decay equation conserves nucleon number and electric charge.'),('Explain why predicting an individual nucleus’s decay time differs from predicting the trend in a large sample.',['Individual decay is random / probabilistic.','A large population has a predictable statistical decay trend.','Half-life predicts the average fraction remaining, not a schedule for a chosen nucleus.']),[check('A neutron has quark composition:',['uud','udd','uuu','ddd'],1,'A neutron contains one up and two down quarks.'),check('Beta-minus decay changes a neutron into:',['A proton, electron and electron antineutrino','Only a proton','An alpha particle','Two neutrons'],0,'Charge and lepton number are conserved in n → p + e− + antineutrino.')],'nucleus')
add('y11-nuclear-equations-half-life',('Describe what changes in the nucleus during beta-minus decay.',['A neutron becomes a proton, emitting an electron and an electron antineutrino.','Atomic number increases by one while mass number stays constant.']),num('A source starts with 9600 undecayed nuclei. Half-life is 4.0 h. Find the expected undecayed number after 12.0 h.','N = N₀(½)^(t/T½).','N = 9600(½)³.','Expected N = 1200 nuclei.'),num('A detector measures 920 counts min⁻¹ initially, including background of 40 counts min⁻¹. After two half-lives, find the expected total count rate.','Initial net source rate = total − background.','Initial net rate = 920 − 40 = 880 counts min⁻¹.','After two half-lives, net = 880 / 4 = 220; total = 260 counts min⁻¹.','Background is added back after source decay; it does not halve with the source.'),('Explain why background must be subtracted before estimating a half-life from detector count rates.',['Measured counts include radiation not emitted by the source.','Only the source’s net rate follows its decay law.','Using totals biases the apparent decay ratio / half-life, particularly when the source becomes weak.']),[check('After four half-lives, the expected remaining fraction is:',['¼','⅛','1/16','1/4⁴'],2,'(½)⁴ = 1/16.'),check('In gamma emission, mass number and atomic number:',['Both decrease','Both increase','Remain unchanged','Swap values'],2,'Gamma emission removes excitation energy without changing nuclear composition.')],'decay')
add('y11-radiation-dose',('Distinguish activity from absorbed dose, including units.',['Activity is decay rate measured in becquerels (decays per second).','Absorbed dose is energy deposited per kilogram, measured in grays (J kg⁻¹).']),num('A 0.020 kg tissue sample absorbs 0.0012 J from radiation. Calculate absorbed dose.','D = E / m.','D = 0.0012 / 0.020.','D = 0.060 Gy.'),num('Using the simplified equivalent-dose model H = wR D, compare 0.060 Gy from gamma radiation (wR = 1) with the same absorbed dose from alpha radiation (wR = 20).','H = wR D.','Gamma: H = 1 × 0.060 = 0.060 Sv.','Alpha: H = 20 × 0.060 = 1.2 Sv.','The alpha equivalent dose is twenty times greater for equal absorbed dose; this is not a full effective-dose calculation.'),('Explain why an alpha emitter can pose a greater hazard inside the body than outside intact skin.',['Alpha radiation has short penetration and can be stopped by outer skin / thin material.','Inside tissue it deposits energy densely along a short path, producing strong ionisation.','Internal uptake places the source close to sensitive cells, so external shielding alone is insufficient.']),[check('A count rate is best reduced to an estimate of source rate by:',['Adding background','Subtracting background','Multiplying by tissue mass','Dividing by dose'],1,'Subtract background before analysing source counts.'),check('One gray equals:',['One decay per second','One joule per kilogram','One coulomb per second','One watt per square metre'],1,'Gy measures absorbed energy per mass.')],'radiation')
add('y11-nuclear-energy',('Distinguish nuclear fission from fusion.',['Fission splits a heavy nucleus into smaller nuclei.','Fusion combines light nuclei into a heavier nucleus; energy release depends on the binding-energy change.']),num('A nuclear reaction has mass decrease 0.0020 u. Use 1 u c² = 931.5 MeV. Calculate released energy.','E = Δm c².','E = 0.0020 × 931.5 MeV.','E = 1.863 MeV, approximately 1.9 MeV.'),num('Each fission releases 200 MeV. A reactor has thermal power 6.0 × 10⁸ W. Use 1 eV = 1.60 × 10⁻¹⁹ J. Find fissions per second and electrical power at 35% efficiency.','Energy per fission = 200 × 10⁶ × 1.60 × 10⁻¹⁹ = 3.20 × 10⁻¹¹ J.','Fission rate = power / energy per fission.','Rate = 6.0 × 10⁸ / 3.20 × 10⁻¹¹ = 1.875 × 10¹⁹ s⁻¹.','Electrical power = 0.35 × 6.0 × 10⁸ = 2.1 × 10⁸ W.'),('Explain the distinct roles of a moderator and control rods in a thermal-neutron fission reactor.',['The moderator slows neutrons through collisions, improving the probability of further fission in suitable fuel.','Control rods absorb neutrons.','Changing rod insertion changes the number of neutrons available for the chain reaction / power control.']),[check('Nuclear binding energy is associated with:',['Energy needed to separate a nucleus into its nucleons','Energy needed to remove only one orbital electron','Temperature alone','Rest mass of emitted light only'],0,'Binding energy measures the energy required to separate the bound nucleus.'),check('In an energy-releasing nuclear reaction, the products have total rest mass that is:',['Larger','Smaller','Necessarily identical','Zero'],1,'The mass decrease corresponds to released energy.')],'fission')
add('y11-charge-current-voltage',('Distinguish current from potential difference with units.',['Current is charge transfer rate, I = Q / t, in amperes.','Potential difference is energy transferred per charge, V = E / Q, in volts.']),num('A circuit carries 0.40 A for 75 s. Calculate charge passing a point.','Q = It.','Q = 0.40 × 75.','Q = 30 C.'),num('A 9.0 V supply transfers energy to 30 C of charge. Find the transferred energy and the power if this occurs in 75 s.','E = VQ.','E = 9.0 × 30 = 270 J.','P = E / t = 270 / 75 = 3.6 W.','The same result follows from P = VI with I = 0.40 A.'),('Explain how to connect an ammeter and voltmeter to measure current through and potential difference across a resistor.',['Place the ammeter in series so the resistor’s current passes through it.','Place the voltmeter in parallel across the resistor.','A low-resistance ammeter and high-resistance voltmeter minimise disturbance of the circuit.']),[check('Conventional current direction in a metal is:',['The electron drift direction','Opposite the electron drift direction','Random at all times','Always downward'],1,'Conventional current follows positive-charge motion.'),check('One volt is:',['One coulomb per second','One joule per coulomb','One joule per second','One ampere per metre'],1,'Potential difference is energy per charge.')],'circuit')
add('y11-resistance-energy-power',('State the condition under which a component obeys Ohm’s law.',['Potential difference is proportional to current / V = IR with constant R.','Physical conditions, particularly temperature, must remain constant.']),num('A resistor has 12 V across it and current 0.30 A. Find resistance and power.','R = V / I and P = VI.','R = 12 / 0.30 = 40 Ω.','P = 12 × 0.30 = 3.6 W.'),num('A 1.8 kW heater runs for 2.5 h. Electricity costs $0.32 per kWh. Find energy in kWh and cost.','Energy in kWh = power in kW × time in h.','E = 1.8 × 2.5 = 4.5 kWh.','Cost = 4.5 × $0.32 = $1.44.','A kWh is an energy unit, not a power unit.'),('Explain why an incandescent lamp can have a curved current–voltage graph.',['Increasing current heats the filament.','Its resistance rises with temperature over the usual operating range.','Current therefore is not proportional to voltage; the filament is non-ohmic across that range.']),[check('With fixed resistance, doubling voltage makes power:',['Half','Double','Four times','Unchanged'],2,'P = V² / R.'),check('The gradient of a V-versus-I graph for an ohmic resistor is:',['Power','Resistance','Charge','Energy'],1,'V = RI gives slope R.')],'ohmic')
add('y11-series-parallel-circuits',('State the current and voltage relationships for parallel branches.',['The potential difference is the same across each parallel branch.','Total current is the sum of branch currents.']),num('A 6.0 Ω resistor and 3.0 Ω resistor are connected in parallel across 12 V. Find equivalent resistance.','1 / Req = 1 / R₁ + 1 / R₂.','1 / Req = 1 / 6.0 + 1 / 3.0 = 1 / 2.0.','Req = 2.0 Ω.'),num('A 4.0 Ω resistor is placed in series with that parallel pair, across an ideal 18 V supply. Find total current and current in the 3.0 Ω branch.','Total resistance = 4.0 + 2.0 = 6.0 Ω.','Total current = 18 / 6.0 = 3.0 A.','Parallel-pair voltage = 3.0 × 2.0 = 6.0 V; 3.0 Ω branch current = 6.0 / 3.0 = 2.0 A.','The 6.0 Ω branch carries 1.0 A, so branch currents sum to 3.0 A.'),('Explain what happens to total current if one of two parallel resistive branches is removed from an ideal fixed-voltage source.',['The remaining branch still has the same source voltage.','Removing a conducting branch increases equivalent resistance.','Total current decreases, while current in the unchanged branch is unchanged.']),[check('Adding a resistor in series increases total resistance, so fixed-voltage supply current:',['Increases','Decreases','Stays equal','Becomes negative'],1,'I = V / R.'),check('At a junction, current conservation reflects conservation of:',['Charge','Resistance','Temperature','Voltage alone'],0,'Charge does not accumulate in a steady-state junction.')],'parallel')
add('y11-components-ac-safety',('Explain the roles of a fuse and an earth connection in mains protection.',['A fuse opens the circuit when current causes sufficient heating, protecting against excessive current.','An earth connection provides a low-resistance fault path from exposed metal, helping protective devices disconnect the supply.']),num('An ideal 230 V DC supply powers a 920 W resistive device. Find its current and resistance.','I = P / V and R = V² / P.','I = 920 / 230 = 4.0 A.','R = 230² / 920 = 57.5 Ω.'),num('A 9.0 V DC supply powers an LED with 2.0 V forward drop at 0.020 A. Find series resistance and resistor power.','Resistor voltage = supply − LED drop = 7.0 V.','R = 7.0 / 0.020 = 350 Ω.','P = 7.0 × 0.020 = 0.14 W.','Choose a resistor rating above 0.14 W and a suitable standard resistance; an LED needs current limiting.'),('Explain how an RCD detects a fault and why it does not replace all other protective measures.',['It compares currents in active and neutral conductors.','A difference indicates current returning by another path / leakage, causing rapid disconnection above the trip condition.','It is not complete protection against every fault, including balanced active-to-neutral contact; insulation and other protection remain necessary.']),[check('For a sinusoidal AC supply, the rms voltage represents:',['The peak voltage','The DC voltage giving the same average heating in a resistor','Always zero voltage','Twice the peak voltage'],1,'Rms relates AC to equal average resistive power.'),check('An ideal diode mainly allows current:',['In both directions equally','In one forward direction','Only through air','Only at zero voltage'],1,'Its rectifying behaviour favours forward conduction.')],'led')
add('static-equilibrium',('State the two independent conditions for static equilibrium of a rigid body in a plane.',['Resultant force is zero in every direction.','Resultant torque about any point is zero.']),num('A 4.0 m horizontal uniform beam of weight 120 N is hinged at its left end. A vertical support force acts at its right end. Find that force when no other load is present.','Take moments about the hinge: support force × 4.0 = weight × 2.0.','4.0F = 120 × 2.0.','F = 60 N upward.'),num('A 180 N load is added 3.0 m from the hinge on the same beam. Find the right support force and the vertical hinge force.','Moment balance: 4.0F = 120 × 2.0 + 180 × 3.0.','F = 780 / 4.0 = 195 N upward.','Vertical force balance: H + 195 − 120 − 180 = 0, so H = 105 N upward.','Both force and torque balance are satisfied; the load increases the right support’s share.'),('Explain why lowering an object’s centre of mass can improve its resistance to toppling.',['Toppling becomes possible when the weight’s line of action passes outside the support base.','A lower centre of mass generally needs a larger tilt for the line of action to leave a given base.','The gravitational torque then tends to restore the object over a greater range of small tilts.']),[check('Torque magnitude uses:',['Force × perpendicular lever arm','Mass × velocity','Force / distance','Power × time'],0,'The perpendicular distance to the force line determines torque.'),check('Zero net force alone guarantees a rigid body has:',['No angular acceleration','No translational acceleration','Zero torque','Zero angular velocity'],1,'A force couple can produce torque while net force is zero.')],'beam')
add('inclined-planes',('Resolve the weight of a mass on a slope of angle θ into parallel and perpendicular components.',['Parallel component is mg sin θ down the slope.','Perpendicular component is mg cos θ into the slope.']),num('A frictionless sled starts from rest on a 25° incline. Find its downslope acceleration using g = 9.8 m s⁻².','a = g sin θ.','a = 9.8 sin 25°.','a = 4.14 m s⁻² downslope.'),num('The sled travels 8.0 m down the slope from rest. Calculate final speed and compare it with an energy method.','v² = u² + 2as.','v = √(2 × 4.14 × 8.0) = 8.14 m s⁻¹.','Energy method: mgh = ½mv² with h = 8.0 sin 25° gives v = √(2g × 8.0 sin 25°).','Both methods give approximately 8.1 m s⁻¹ because the same frictionless assumptions apply.'),('A sled descends a slope at constant speed with no pulling force. Explain the balance of forces along the slope.',['Constant velocity means zero acceleration and zero net parallel force.','Friction acts upslope and balances mg sin θ.','The normal force balances the perpendicular component, not the full weight.']),[check('For a frictionless slope, increasing angle from 0° toward 90° makes acceleration:',['Decrease','Increase toward g','Stay at zero','Exceed g'],1,'a = g sin θ approaches g.'),check('A block moving down a slope has kinetic friction directed:',['Downslope','Upslope','Perpendicular into the surface','Vertically down'],1,'Friction opposes sliding along the slope.')],'slope')
add('grav-fields',('Distinguish gravitational field strength from gravitational force.',['Field strength is gravitational force per unit test mass, in N kg⁻¹.','Force on a mass m is F = mg; force depends on the test mass as well as the field.']),num('At a planet’s surface, g = 12 N kg⁻¹. At twice the planet’s radius from its centre, find field strength outside the spherical planet.','g ∝ 1 / r² outside a spherical mass.','g₂ = 12 × (R / 2R)².','g₂ = 3.0 N kg⁻¹.'),num('A planet has mass 4.8 × 10²⁴ kg and radius 5.8 × 10⁶ m. Use G = 6.67 × 10⁻¹¹ N m² kg⁻². Find surface g and the weight of a 65 kg person there.','g = GM / R².','g = (6.67 × 10⁻¹¹ × 4.8 × 10²⁴) / (5.8 × 10⁶)² = 9.52 N kg⁻¹.','Weight = mg = 65 × 9.52 = 619 N.','The person’s mass remains 65 kg; weight changes with the local field.'),('Explain why a field diagram uses arrows pointing toward a spherical planet and why arrow spacing / density changes with distance.',['Gravity is attractive, so force on a positive test mass points toward the planet.','Outside the planet, field strength decreases with inverse square of centre-to-centre distance.','A valid field model indicates a weaker field farther out; it does not use altitude alone as r.']),[check('The gravitational force between two masses at separation r doubles one mass and doubles r. Force becomes:',['Half','Unchanged','Double','Four times'],0,'F scales as 2 / 2² = ½.'),check('The unit N kg⁻¹ is equivalent to:',['m s⁻¹','m s⁻²','kg m s⁻¹','J s'],1,'Force / mass has acceleration units.')],'gravity')
add('grav-energy',('State the sign and reference convention for U = −GMm/r.',['The zero of gravitational potential energy is chosen at infinite separation.','Finite separation gives negative U for attractive gravity.']),num('A 500 kg spacecraft is at radius 7.0 × 10⁶ m from a planet’s centre. Use GM = 4.0 × 10¹⁴ m³ s⁻². Calculate U.','U = −GMm / r.','U = −(4.0 × 10¹⁴ × 500) / (7.0 × 10⁶).','U = −2.86 × 10¹⁰ J.'),num('The spacecraft is moved slowly from radius 7.0 × 10⁶ m to 1.4 × 10⁷ m, with negligible change in kinetic energy. Find work by the external agent.','External work = ΔU = GMm(1/r₁ − 1/r₂).','ΔU = 4.0 × 10¹⁴ × 500 × (1/(7.0 × 10⁶) − 1/(1.4 × 10⁷)).','Wexternal = +1.43 × 10¹⁰ J.','Gravity does negative work; the spacecraft becomes less tightly bound as U increases toward zero.'),('Explain why mgh is unsuitable for a very large change in distance from a planet.',['mgh assumes approximately constant g.','The field weakens substantially over large radial changes.','Use ΔU from −GMm/r or integrate the changing force instead.']),[check('Moving outward from a planet toward infinity makes U:',['More negative','Increase toward zero','Remain constant','Become positive immediately'],1,'With zero at infinity, U approaches zero from below.'),check('Work done by gravity during outward motion is:',['Positive','Negative','Zero for every trajectory','Equal to mass'],1,'Force and radial displacement oppose each other.')],'gravity')
add('projectile',('State why horizontal and vertical motion may be analysed independently for an ideal projectile.',['The acceleration is vertically downward, with no horizontal component when air resistance is neglected.','Perpendicular components evolve under their own equations over the same elapsed time.']),num('A projectile is launched horizontally at 16 m s⁻¹ from a height of 19.6 m. Use g = 9.8 m s⁻². Find time to land.','h = ½gt² because initial vertical velocity is zero.','t = √(2 × 19.6 / 9.8).','t = 2.0 s.'),num('For the same projectile, calculate horizontal range and speed immediately before landing.','Horizontal range = vx t = 16 × 2.0 = 32 m.','Vertical impact velocity magnitude = gt = 19.6 m s⁻¹.','Impact speed = √(16² + 19.6²) = 25.3 m s⁻¹.','Velocity is approximately 50.8° below horizontal; horizontal velocity remains 16 m s⁻¹.'),('Two balls leave the same height simultaneously, one dropped and one launched horizontally. Explain their landing times under the ideal model.',['They have the same initial vertical velocity of zero.','They experience the same vertical acceleration and fall through the same height.','Their vertical motions and landing times match; horizontal velocity does not delay the fall in this model.']),[check('At the highest point of an oblique projectile’s flight, vertical velocity is:',['Zero','Equal to horizontal velocity','Equal to g','Maximum upward'],0,'Vertical velocity changes sign through zero at the top.'),check('In ideal projectile motion, horizontal acceleration is:',['g','−g','Zero','Equal to horizontal speed'],2,'Gravity has no horizontal component in the chosen axes.')],'projectile')
add('circular',('Explain why constant-speed circular motion is accelerated motion.',['Velocity changes because its direction changes.','Acceleration points toward the circle’s centre.']),num('A 0.80 kg object moves at 6.0 m s⁻¹ in a circle of radius 1.5 m. Find centripetal acceleration and net inward force.','a = v² / r and Fnet = ma.','a = 6.0² / 1.5 = 24 m s⁻².','Fnet = 0.80 × 24 = 19.2 N inward.'),num('A vehicle rounds a level bend of radius 50 m. The maximum static-friction coefficient is 0.60. Find the maximum speed in the ideal friction-limited model; use g = 9.8 m s⁻².','Maximum friction μmg provides required mv²/r.','vmax = √(μgr).','vmax = √(0.60 × 9.8 × 50) = 17.1 m s⁻¹.','Mass cancels; this model neglects banking, changing friction and other lateral forces.'),('Explain why “centripetal force” should not be drawn as an additional force on a free-body diagram of a car turning on a level road.',['Centripetal describes the required net inward force, not a new interaction.','Static friction supplies the inward horizontal force in this model.','Adding both friction and a separate centripetal force double-counts the inward force.']),[check('At fixed radius, doubling speed multiplies inward acceleration by:',['½','2','4','8'],2,'a = v² / r.'),check('If the inward force suddenly vanishes, the object initially moves:',['Radially outward','Along the tangent','Toward the centre','Along the original circle'],1,'Without inward acceleration, velocity continues tangentially.')],'circle')
add('orbits',('State what supplies centripetal force in a circular satellite orbit and define orbital radius.',['Gravitational attraction provides the net inward force.','Orbital radius is distance from the planet’s centre, not height above its surface.']),num('A satellite orbits at radius 8.0 × 10⁶ m. Use GM = 4.0 × 10¹⁴ m³ s⁻². Find circular orbital speed.','GMm/r² = mv²/r, so v = √(GM/r).','v = √(4.0 × 10¹⁴ / 8.0 × 10⁶).','v = 7.07 × 10³ m s⁻¹.'),num('Find the period of that orbit and the factor by which period changes if orbital radius doubles.','T = 2πr / v.','T = 2π × 8.0 × 10⁶ / 7071 = 7109 s, about 1.97 h.','Kepler scaling T ∝ r^(3/2) gives factor 2^(3/2) = 2.83.','The period grows by about 2.83 for the same central mass, not merely by two.'),('Explain why an orbiting astronaut can feel weightless even when Earth’s gravitational field is substantial.',['Gravity still acts on astronaut and spacecraft.','Both are in continuous free fall with similar orbital acceleration.','There is little supporting normal force on the astronaut; apparent weight is small, not gravitational force zero.']),[check('For circular orbits around the same planet, larger radius gives orbital speed that is:',['Higher','Lower','Unchanged','Zero'],1,'v ∝ r⁻½.'),check('Kepler’s third law relates period and semi-major axis by:',['T ∝ a³','T² ∝ a³','T³ ∝ a²','T ∝ a'],1,'For a fixed central mass, T²/a³ is constant.')],'orbit')
add('relativity-foundations',('State Einstein’s two postulates for special relativity.',['The laws of physics are the same in all inertial reference frames.','Light in vacuum has the same speed c for all inertial observers, independent of source motion.']),num('A train moves at 24 m s⁻¹ relative to the ground. A person walks forward at 1.5 m s⁻¹ relative to the train. Use the low-speed classical approximation to find ground speed.','vground ≈ vtrain + vperson relative to train.','vground ≈ 24 + 1.5.','vground ≈ 25.5 m s⁻¹ in the train’s direction.'),num('A spaceship moves at 0.60c relative to Earth. A lamp on its front emits light forward. State the light speed measured inside the ship and on Earth, then assess a prediction of 1.60c.','The ship measures vacuum light speed c.','Earth also measures vacuum light speed c.','The classical sum c + 0.60c = 1.60c is inapplicable to this relativistic light case.','Both measurements satisfy Einstein’s light-speed postulate; velocities require relativistic transformation at such speeds.'),('Explain why uniform straight-line motion differs from acceleration when identifying inertial frames.',['An inertial frame has no acceleration relative to another inertial frame.','Uniform straight-line relative motion does not distinguish a preferred inertial frame.','An accelerating frame is non-inertial and cannot be treated identically without additional inertial effects.']),[check('An observer moving toward a vacuum light beam measures its speed as:',['c plus observer speed','c minus observer speed','c','Zero'],2,'Vacuum light speed is invariant for inertial observers.'),check('Which is an inertial-frame example in the ideal model?',['A uniformly turning car','A braking train','A spacecraft in constant-velocity straight-line motion','A spinning platform'],2,'Constant velocity means no acceleration.')],'frames')
add('relativity-effects',('Define proper time and proper length.',['Proper time is measured by a clock present at both events at the same spatial position in its rest frame.','Proper length is the length measured in the object’s rest frame.']),num('A spacecraft travels at 0.80c. Calculate its Lorentz factor.','γ = 1 / √(1 − v²/c²).','γ = 1 / √(1 − 0.80²) = 1 / 0.60.','γ = 1.667.'),num('A spacecraft’s onboard journey time is 6.0 years and its rest length is 90 m. It travels at 0.80c. Find Earth-frame elapsed time and length along motion.','Use γ = 1.667, Δt = γΔτ and L = L₀/γ.','Earth-frame time = 1.667 × 6.0 = 10.0 years.','Earth-frame length = 90 / 1.667 = 54 m.','The onboard time is proper time for the departure / arrival events on the ship; its rest-frame length is proper length.'),('Explain why a fast muon’s longer Earth-frame lifetime does not mean its own clock runs abnormally in its rest frame.',['The muon’s rest-frame lifetime is its proper time.','Earth assigns a dilated time interval to the moving muon.','The difference is between frame measurements, not a defective clock or altered local decay physics.']),[check('Length contraction applies to dimensions:',['Along relative motion','Perpendicular only','In every direction equally','Only at rest'],0,'Only the parallel length contracts in this standard comparison.'),check('As v approaches c from below, γ:',['Approaches zero','Approaches one','Increases without bound','Becomes negative'],2,'The denominator tends to zero from above.')],'relativity')
add('relativity-energy',('Distinguish rest energy from total relativistic energy.',['Rest energy is E₀ = mc².','Total energy is E = γmc² and includes rest plus kinetic energy.']),num('A particle of rest mass 2.0 × 10⁻²⁷ kg moves at 0.60c. Use c = 3.0 × 10⁸ m s⁻¹. Find relativistic momentum.','p = γmv with γ = 1 / √(1 − 0.60²) = 1.25.','p = 1.25 × 2.0 × 10⁻²⁷ × 1.8 × 10⁸.','p = 4.5 × 10⁻¹⁹ kg m s⁻¹.'),num('For the same particle, calculate rest energy and kinetic energy.','E₀ = mc² and K = (γ − 1)mc².','E₀ = 2.0 × 10⁻²⁷ × (3.0 × 10⁸)² = 1.8 × 10⁻¹⁰ J.','K = 0.25 × 1.8 × 10⁻¹⁰ = 4.5 × 10⁻¹¹ J.','Total energy is 2.25 × 10⁻¹⁰ J; kinetic energy is not the full γmc².'),('Explain why adding energy cannot accelerate a particle with non-zero rest mass to c.',['γ grows without bound as v approaches c.','Required total energy γmc² consequently grows without bound.','Finite added energy can bring speed closer to c but cannot reach c for a massive particle.']),[check('For a particle at rest, its relativistic momentum is:',['mc','mc²','Zero','Infinite'],2,'p = γmv is zero when v = 0.'),check('At high speed, classical ½mv² is:',['Always exact','A low-speed approximation','Equal to total rest energy','Independent of speed'],1,'Relativistic kinetic energy is (γ − 1)mc².')],'relativity')
add('general-relativity',('Describe gravitational time dilation and identify which stationary clock runs more slowly in a weak-field comparison.',['Clocks at different gravitational potentials can accumulate different proper times.','A stationary clock lower in the gravitational potential runs more slowly relative to a higher stationary clock in the weak-field comparison.']),num('Use the weak-field approximation Δf/f ≈ gh/c² for stationary clocks separated vertically by 1500 m. With g = 9.8 m s⁻² and c = 3.0 × 10⁸ m s⁻¹, find the fractional rate difference.','Fractional difference ≈ gh/c².','9.8 × 1500 / (3.0 × 10⁸)².','Fractional difference ≈ 1.63 × 10⁻¹³.'),num('Using that fractional difference, estimate how much extra time the higher clock accumulates over 86400 s. State the assumptions.','Extra accumulated time ≈ time × fractional rate difference.','Δt ≈ 86400 × 1.63 × 10⁻¹³.','Δt ≈ 1.41 × 10⁻⁸ s, about 14.1 ns.','This is a stationary, weak-field, nearly constant-g estimate; relative-motion effects are excluded.'),('Explain why satellite navigation must account for both gravitational and motion-related clock effects.',['Satellite and surface clocks are at different gravitational potentials.','Satellite motion also produces special-relativistic time dilation in the relevant frame comparison.','Uncorrected timing differences translate into position errors because signals travel at light speed.']),[check('Gravitational lensing is associated with:',['Light following paths affected by spacetime curvature','Light losing all frequency','Only mechanical refraction in glass','Electric attraction of photons'],0,'Mass–energy curves spacetime, affecting light paths.'),check('A black-hole event horizon is:',['Always a solid surface','A boundary beyond which future light signals cannot escape to distant observers','The centre of every star','A region with no gravity'],1,'It is a causal boundary, not a material shell.')],'clocks')
add('electric-fields',('Distinguish electric field strength from electric force and state the field direction convention.',['Electric field is force per unit positive test charge, E = F/q.','Field direction is the force direction on a positive charge; negative charges experience force opposite the field.']),num('A charge of +3.0 μC experiences a 0.012 N force east. Find electric field.','E = F / q.','E = 0.012 / (3.0 × 10⁻⁶).','E = 4.0 × 10³ N C⁻¹ east.'),num('Parallel plates are separated by 0.025 m with potential difference 300 V. Find the uniform field magnitude and initial acceleration magnitude of an electron released from rest. Use e = 1.60 × 10⁻¹⁹ C and me = 9.11 × 10⁻³¹ kg.','E = V / d = 300 / 0.025 = 1.20 × 10⁴ V m⁻¹.','Force magnitude = eE = 1.92 × 10⁻¹⁵ N.','Acceleration = F / me = 2.11 × 10¹⁵ m s⁻².','The electron accelerates opposite the electric field; the calculation neglects other forces and edge effects.'),('Explain how electric field-line diagrams indicate a stronger field and why field lines cannot cross at one point.',['Greater line density represents greater field strength in the model.','At any given point the electric field has one resultant direction.','Crossing would imply two different field directions at the same point, making the diagram inconsistent.']),[check('Between ideal parallel plates, doubling voltage at fixed spacing makes E:',['Half','Double','Four times','Unchanged'],1,'E = V/d.'),check('Two like point charges exert forces that are:',['Attractive','Repulsive','Always zero','Perpendicular to their separation'],1,'Like charges repel along the line joining them.')],'electric')
add('magnetic-fields',('State the conditions for a moving charge to experience magnetic force and whether that force does work on an ideal point charge.',['Force requires a velocity component perpendicular to the magnetic field / F = qvB sin θ.','The magnetic force is perpendicular to velocity and does no work on the ideal charge.']),num('A proton moves at 2.0 × 10⁶ m s⁻¹ perpendicular to a 0.15 T field. Use q = 1.60 × 10⁻¹⁹ C. Find force magnitude.','F = qvB for perpendicular motion.','F = 1.60 × 10⁻¹⁹ × 2.0 × 10⁶ × 0.15.','F = 4.8 × 10⁻¹⁴ N.'),num('Using proton mass 1.67 × 10⁻²⁷ kg, calculate the radius of its circular path in that field using the non-relativistic model.','qvB = mv²/r, so r = mv/(qB).','r = (1.67 × 10⁻²⁷ × 2.0 × 10⁶) / (1.60 × 10⁻¹⁹ × 0.15).','r = 0.139 m.' ,'The force changes velocity direction while speed stays constant when magnetic force is the only force.'),('Explain the force on a current-carrying straight wire aligned parallel to a uniform magnetic field.',['Wire force magnitude is F = BIL sin θ.','Parallel alignment gives θ = 0° and sin θ = 0.','The magnetic force on this ideal straight section is zero, despite non-zero current and field.']),[check('A moving electron’s force direction relative to a positive charge at the same velocity is:',['The same','Opposite','Always zero','Along velocity'],1,'Changing the charge sign reverses magnetic force.'),check('At fixed q, v and B, magnetic force is largest when motion is:',['Parallel to B','Antiparallel to B','Perpendicular to B','At rest'],2,'sin θ is maximal at 90°.')],'magnetic')
add('motors',('Explain how forces on a current-carrying rectangular coil produce rotation in a magnetic field.',['Opposite coil sides experience forces in opposite directions.','When their lines of action form a couple, the forces produce a torque.']),num('A straight 0.12 m coil side carries 2.5 A perpendicular to a 0.40 T field. Find magnetic force on that side.','F = BIL sin θ, with sin 90° = 1.','F = 0.40 × 2.5 × 0.12.','F = 0.12 N.'),num('A 60-turn coil has area 0.0040 m², current 2.5 A and field 0.40 T. Find maximum torque and torque when its normal makes 30° with the field.','τ = NBIA sin θ, where θ is between coil normal and B.','Maximum torque = 60 × 0.40 × 2.5 × 0.0040 = 0.24 N m.','At θ = 30°, τ = 0.24 sin 30° = 0.12 N m.','Torque is zero when the coil normal is parallel to the field, and maximal when perpendicular.'),('Explain why a simple DC motor uses a split-ring commutator.',['Without current reversal, the coil’s torque direction would reverse as it passes the alignment position.','The commutator reverses coil current every half-turn.','This maintains torque in the same rotational sense through successive half-turns in the ideal motor.']),[check('At fixed B, I, A and angle, doubling turns makes coil torque:',['Half','Unchanged','Double','Four times'],2,'Torque is proportional to N.'),check('A motor primarily converts:',['Mechanical energy to electrical energy','Electrical energy to mechanical energy','Heat to nuclear energy','Mass to charge'],1,'Electrical input drives rotation.')],'coil')
add('induction',('Define magnetic flux through a flat area and distinguish flux from flux density.',['Flux is Φ = BA cos θ for a uniform field, with θ measured to the area normal, in webers.','Flux density B is field strength in teslas; flux also depends on area and orientation.']),num('A 40-turn coil’s flux per turn falls uniformly from 0.0060 Wb to 0.0010 Wb in 0.10 s. Find average induced emf magnitude.','|εavg| = N|ΔΦ|/Δt.','|εavg| = 40 × |0.0010 − 0.0060| / 0.10.','|εavg| = 2.0 V.'),num('A 0.25 m rod moves at 4.0 m s⁻¹ perpendicular to its length and to a 0.30 T field. It completes a circuit of total resistance 1.5 Ω. Find emf and current.','Motional emf ε = BLv.','ε = 0.30 × 0.25 × 4.0 = 0.30 V.','I = ε/R = 0.30/1.5 = 0.20 A.','The induced effect opposes the motion that produces the flux change; maintaining speed requires work.'),('A magnet approaches a conducting loop. Explain Lenz’s law and the energy implication.',['Induced current creates a magnetic field opposing the change in flux.','The resulting interaction resists the approach in this setup.','External work supplies electrical / thermal energy; spontaneous reinforcement of approach would violate energy conservation.']),[check('A stationary coil in a constant uniform field has induced emf:',['Always large','Zero if flux is constant','Equal to B','Equal to its resistance'],1,'Induction requires a change in flux linkage.'),check('For the same total flux change, halving the time makes average emf magnitude:',['Half','Double','Unchanged','Four times'],1,'Average emf is inversely proportional to change time.')],'induction')
add('generators',('Explain the energy conversion and induction principle in a simple AC generator.',['Mechanical work rotates a coil / field arrangement, changing magnetic flux linkage.','The changing flux induces alternating emf, converting mechanical input to electrical output.']),num('A sinusoidal generator has peak emf 80 V. Calculate rms emf.','Vrms = Vpeak/√2 for a sine wave.','Vrms = 80/√2.','Vrms = 56.6 V.'),num('An ideal generator has 100 turns, field 0.20 T, area 0.010 m² and frequency 50 Hz. Find angular speed and peak emf.','ω = 2πf.','ω = 2π × 50 = 314 rad s⁻¹.','εpeak = NBAω = 100 × 0.20 × 0.010 × 314 = 62.8 V.','Doubling rotational frequency would double peak emf for unchanged N, B and A.'),('Explain why emf is zero when a rotating coil’s flux is momentarily maximum.',['Induced emf depends on rate of change of flux, not flux magnitude.','At a smooth maximum in flux, the instantaneous slope dΦ/dt is zero.','Therefore induced emf is zero there; its magnitude is largest when flux changes fastest.']),[check('For a sinusoidal output, frequency 25 Hz means period:',['0.04 s','25 s','50 s','0.5 s'],0,'Period is 1/f.'),check('A loaded generator needs more driving torque because:',['Lenz’s law gives an opposing electromagnetic torque','Magnetic flux disappears','Energy is created','Resistance cannot dissipate energy'],0,'Mechanical work supplies the electrical output and losses.')],'generator')
add('transformers',('State why an ordinary transformer requires changing current and describe its two coupled coils.',['Changing primary current produces changing magnetic flux in the core.','This changing flux links the secondary and induces emf; steady DC gives no sustained ideal secondary emf.']),num('An ideal transformer has 800 primary turns and 200 secondary turns. Primary rms voltage is 240 V. Find secondary rms voltage.','Vs/Vp = Ns/Np.','Vs = 240 × 200/800.','Vs = 60 V.'),num('The secondary supplies 3.0 A at 60 V. Find ideal primary current and resistive loss in a 4.0 Ω transmission line carrying the primary current.','Ideal powers match: VpIp = VsIs.','Ip = 60 × 3.0 / 240 = 0.75 A.','Line loss = Ip²R = 0.75² × 4.0 = 2.25 W.','The loss concerns the specified primary-side line; it is not an assumed loss inside the ideal transformer.'),('Explain why stepping up voltage reduces transmission heating for a fixed delivered power.',['For fixed power P, increasing voltage lowers current I = P/V.','Resistive line loss is I²R.','Lower current greatly reduces line heating, while practical transformers and lines still have losses.']),[check('A step-up ideal transformer has Ns > Np. Its secondary current at equal power is:',['Higher','Lower','Equal','Always zero'],1,'Higher voltage implies lower current for equal power.'),check('Doubling line current at fixed R makes heating power:',['Half','Double','Four times','Unchanged'],2,'P loss = I²R.')],'transformer')
add('quantum',('Distinguish photon energy from the intensity of monochromatic light.',['Photon energy is E = hf, set by frequency.','At fixed frequency, greater intensity corresponds to more energy / photons arriving per unit area per time, not higher energy per photon.']),num('Find photon energy for frequency 7.5 × 10¹⁴ Hz. Use h = 6.63 × 10⁻³⁴ J s.','E = hf.','E = 6.63 × 10⁻³⁴ × 7.5 × 10¹⁴.','E = 4.97 × 10⁻¹⁹ J.'),num('A metal has work function 2.1 eV and is illuminated by 3.4 eV photons. Find maximum photoelectron kinetic energy in eV and joules, and stopping potential. Use 1 eV = 1.60 × 10⁻¹⁹ J.','Kmax = Ephoton − φ.','Kmax = 3.4 − 2.1 = 1.3 eV.','Kmax = 1.3 × 1.60 × 10⁻¹⁹ = 2.08 × 10⁻¹⁹ J; stopping potential magnitude = 1.3 V.','The stopping potential depends on maximum kinetic energy per electron charge, not directly on beam intensity.'),('Explain why increasing intensity below threshold frequency does not cause photoelectric emission in the basic single-photon model.',['Each photon has energy hf below the work function.','One electron receives energy from one photon in this model.','More subthreshold photons do not supply enough energy per interaction; increasing frequency above threshold is required.']),[check('An electron dropping to a lower atomic energy level:',['Absorbs a photon of arbitrary energy','Emits a photon matching the level difference','Loses its charge','Always leaves the atom'],1,'The photon energy equals the difference between the allowed levels.'),check('The de Broglie wavelength of a particle is:',['hp','p/h','h/p','mc²'],2,'Matter-wave wavelength is inversely proportional to momentum.')],'quantum')
add('particle-physics',('Describe the different roles of electric and magnetic fields in a charged-particle accelerator.',['Electric fields can transfer energy to charges and increase their kinetic energy.','Magnetic fields can bend / guide a beam without doing work on ideal point charges.']),num('An electron is accelerated from rest through 2500 V. Calculate kinetic energy in eV and joules. Use e = 1.60 × 10⁻¹⁹ C.','K = |q|V.','K = 2500 eV = 1.60 × 10⁻¹⁹ × 2500 J.','K = 4.00 × 10⁻¹⁶ J.'),num('A proton has momentum 3.2 × 10⁻¹⁹ kg m s⁻¹ and enters a uniform 0.50 T field perpendicular to its velocity. Use e = 1.60 × 10⁻¹⁹ C. Find curvature radius and the new field needed for the same radius if momentum doubles.','Magnetic bending radius r = p/(|q|B).','r = 3.2 × 10⁻¹⁹ / (1.60 × 10⁻¹⁹ × 0.50) = 4.0 m.','For fixed r and charge, B ∝ p, so doubled momentum requires B = 1.0 T.','Using momentum allows this bending relation to remain valid for relativistic motion.'),('Explain why a fixed-frequency classical cyclotron becomes unsuitable as massive particles become strongly relativistic.',['Relativistic momentum changes the relation between speed, momentum and orbit timing.','The revolution frequency decreases from the low-speed qB/(2πm) value by the γ factor.','Particles lose synchronisation with an unchanged accelerating frequency; timing / field control must be adjusted.']),[check('An electric potential increase of 1 kV accelerates a proton through a kinetic-energy gain of:',['1 eV','1000 eV','1000 J','Zero'],1,'A singly charged particle gains 1000 eV through an accelerating 1000 V difference.'),check('In a synchrotron with fixed bending radius, increasing particle momentum requires magnetic field to:',['Decrease','Increase','Stay zero','Reverse automatically'],1,'B = p/(qr).')],'accelerator')
add('cosmology',('Distinguish cosmological redshift from a change in the locally measured vacuum speed of light.',['Cosmological redshift is the increase in light wavelength as the universe expands during propagation.','Local vacuum light speed remains c; redshift does not mean light travels locally more slowly.']),num('A spectral line emitted at 500 nm is observed at 525 nm. Calculate redshift z.','z = (λobserved − λemitted)/λemitted.','z = (525 − 500)/500.','z = 0.050.'),num('Use the low-redshift approximations v ≈ cz and v = H₀d, with c = 3.0 × 10⁵ km s⁻¹ and H₀ = 70 km s⁻¹ Mpc⁻¹, to estimate distance for z = 0.050.','v ≈ cz = 3.0 × 10⁵ × 0.050 = 15000 km s⁻¹.','d = v/H₀.','d = 15000/70 ≈ 214 Mpc.','This simplified estimate assumes Hubble flow and low redshift; peculiar motion and a full cosmological model are omitted.'),('Give three distinct observations supporting the hot Big Bang model and briefly connect each to the model.',['Large-scale redshift–distance relation supports expansion from a denser earlier state.','Cosmic microwave background supports a hot early universe that cooled as it expanded.','Light-element abundance patterns broadly agree with early-universe nucleosynthesis predictions.']),[check('A low-redshift galaxy with twice the Hubble-flow distance has approximately:',['Half recession speed','Twice recession speed','Same speed','Zero redshift'],1,'At low redshift, v = H₀d.'),check('A parsec and a light-year are units of:',['Time','Distance','Temperature','Energy'],1,'Both measure astronomical distances, despite the name light-year.')],'cosmology')
# Link the independent questions to the existing published Physics lesson sequence.
catalog=json.loads((ROOT/'physics-legacy-standalone-tasks.json').read_text())['tasks']
physics=[t for t in catalog if t['course']=='Physics ATAR']
assert set(DATA)=={t['topic'] for t in physics}, 'Standalone authoring must cover every Physics lesson exactly once.'
out=[]
for lesson in physics:
 body=DATA[lesson['topic']]
 for i,q in enumerate(body['questions'],1):q['id']=lesson['topic']+'-standalone-q'+str(i)
 for i,q in enumerate(body['mastery'],1):q['id']=lesson['topic']+'-standalone-m'+str(i)
 total=sum(q['marks'] for q in body['questions']+body['mastery'])
 out.append({**lesson,**body,'format':'standalone','title':lesson.get('lessonTitle',lesson['title']).removesuffix(' — standalone task')+' — standalone task','lessonTitle':lesson.get('lessonTitle',lesson['title']).removesuffix(' — standalone task'),'lessonUrl':lesson.get('lessonUrl',lesson['url']).replace('&activity=standalone',''),'totalMarks':total,'suggestedMinutes':35,'constants':'Use g = 9.8 m s⁻² unless a question specifies otherwise. Use the constants given in each question. Show working, direction and units where relevant.','instructions':'Focus: '+lesson['focus']+'\nComplete four new written questions and two concept-check questions independently. Show reasoning, equations, substitutions and units. After your attempt, compare your responses with the step-by-step marking tables, correct errors and record one improvement. Written marks are self-reviewed; concept-check marks are automatically checked. Use the linked lesson if you need to revise.'})
(ROOT/'physics-legacy-standalone-tasks.json').write_text(json.dumps({'version':1,'tasks':out},ensure_ascii=False,indent=2)+'\n')
print('Created',len(out),'standalone Physics tasks:',sum(len(t['questions']) for t in out),'written questions and',sum(len(t['mastery']) for t in out),'concept checks.')
